// Callback pyramid:
getUser(id, (err, user) => {
  if (err) return fail(err);
  getPosts(user, (err, posts) => {
    if (err) return fail(err);
    getComments(posts[0], (err, comments) => {
      if (err) return fail(err);
      done(comments);
    });
  });
});

